-- Classic 1.60: vanilla 1.12 maximum durability of every vanilla item the client has (VMaNGOS world_full_14_june_2021
-- item_template.max_durability, newest row up to patch 10). The client data has no durability, so the server worked it out
-- with the retail formula (ObjectMgr FillMaxDurability), which gave 3,496 items a higher maximum, and so a higher repair
-- bill, and 149 items (starting gear and the like) durability they never had. Items not listed (new Forever items) keep
-- the formula. Loaded by ObjectMgr::LoadClassicItemDurability.
CREATE TABLE IF NOT EXISTS `classic_item_durability` (
  `entry` int unsigned NOT NULL,
  `max_durability` smallint unsigned NOT NULL DEFAULT 0 COMMENT 'vanilla max_durability, 0 = never breaks',
  PRIMARY KEY (`entry`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Classic 1.60: vanilla 1.12 item maximum durability';

DELETE FROM `classic_item_durability`;
